<template>
  <section class="review-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 6 · HUMAN TABLE READ</p><h2>真人桌读证据与签署前预检</h2><p>核对三角色实名身份、真实项目、轮次、桌读 session、反馈结构和提交时间；系统不创建签名。</p></div><nav><RouterLink to="/story/stage6-operations">Stage 6 总控</RouterLink><RouterLink to="/story/stage6-revisions">修订工作台</RouterLink></nav></header>
    <div class="truth-lock"><strong>签署前 Ready ≠ 已签署</strong><span>检查结果不落盘、不关闭意见、不授予真人桌读信用；自报 signature、human credit 或 professional pass 均不被接受。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>

    <section class="selector-bar">
      <label>项目<select v-model="selectedBenchmarkId"><option v-for="project in workspace?.projects ?? []" :key="project.benchmark_id" :value="project.benchmark_id">{{ project.source_entry }} · {{ project.readiness_status }}</option></select></label>
      <label>轮次<select v-model.number="selectedRound"><option :value="1">Round 1</option><option :value="2">Round 2</option></select></label>
      <button :disabled="loading" @click="loadTemplate">生成绑定模板</button>
      <button class="primary" :disabled="loading || !editorText" @click="runInspection">{{ loading ? '检查中…' : '运行签署前预检' }}</button>
    </section>

    <section class="workspace-grid">
      <article class="editor-card"><header><div><p class="eyebrow">TABLE READ JSON</p><h3>桌读证据原文</h3></div><span>仅内存</span></header><div class="toolbar"><label>导入 JSON<input type="file" accept=".json,application/json" @change="importFile" /></label><button @click="copyJson">复制 JSON</button><span>{{ copyMessage }}</span></div><textarea v-model="editorText" aria-label="Stage 6 table read evidence JSON" spellcheck="false"/><footer><span>{{ editorText.length.toLocaleString() }} 字符</span><b>不签署 · 不落盘</b></footer></article>

      <article class="result-card"><header><div><p class="eyebrow">SIGNATURE PREFLIGHT</p><h3>身份与证据门禁</h3></div><b :class="inspection?.signature_preflight_ready ? 'ready' : 'blocked'">{{ inspection?.signature_preflight_ready ? 'READY TO REQUEST SIGNATURE' : 'BLOCKED' }}</b></header>
        <div v-if="inspection" class="metrics"><div><span>Schema</span><strong>{{ inspection.schema_valid ? '合法' : '失败' }}</strong></div><div><span>反馈</span><strong>{{ inspection.artifact_summary.feedback_count }}</strong></div><div><span>P0 Ready</span><strong>{{ inspection.checks.p0_readiness_reverified ? '是' : '否' }}</strong></div><div><span>真人信用</span><strong>0</strong></div></div>
        <div v-if="inspection" class="identity-grid"><span>Benchmark <b>{{ inspection.expected_binding.benchmark_id || '—' }}</b></span><span>Real Project <b>{{ inspection.expected_binding.real_project_id || '未绑定' }}</b></span><span>Round <b>{{ inspection.expected_binding.round_number }}</b></span><span>Session <b>{{ inspection.expected_binding.session_reference || '未核验' }}</b></span></div>
        <div v-if="inspection" class="hash-panel"><div><span>原 JSON 文件 SHA-256</span><code>{{ inspection.source_file_sha256 || '—' }}</code></div><div><span>Canonical artifact SHA-256</span><code>{{ inspection.canonical_artifact_sha256 || 'Schema 合法后生成' }}</code></div></div>
        <section v-if="inspection" class="role-grid"><article><span>编剧 / 剧本编辑</span><strong>{{ inspection.artifact_summary.writer_editor_feedback_count }}</strong></article><article><span>类型 / 导演</span><strong>{{ inspection.artifact_summary.director_feedback_count }}</strong></article><article><span>事实 / 文化</span><strong>{{ inspection.artifact_summary.fact_culture_reviewer_feedback_count }}</strong></article><article><span>需证据意见</span><strong>{{ inspection.artifact_summary.evidence_required_feedback_count }}</strong></article></section>
        <section v-if="inspection" class="checks"><h4>签署前检查</h4><div><span v-for="(passed,key) in inspection.checks" :key="key" :class="passed?'ok':'fail'">{{ passed?'✓':'×' }} {{ checkLabel(key) }}</span></div></section>
        <section v-if="inspection?.issues.length" class="issues"><h4>问题 {{ inspection.issues.length }} 项</h4><article v-for="(item,index) in inspection.issues" :key="`${item.code}-${index}`" :class="item.blocking?'blocking':'warning'"><header><b>{{ item.gate.toUpperCase() }}</b><code>{{ item.code }}</code></header><span>{{ item.path || 'root' }}</span><p>{{ item.message }}</p></article></section>
        <div class="safety-grid"><span>Input persisted <b>否</b></span><span>State mutated <b>否</b></span><span>Signature created <b>否</b></span><span>Human credit <b>0</b></span><span>Execution started <b>否</b></span><span>Professional passed <b>否</b></span></div>
      </article>
    </section>
  </section>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import type { Stage6TableReadEvidenceInspectionResult, Stage6TableReadEvidenceInspectorWorkspace } from '@shared/types'
import { getStage6TableReadEvidenceInspector, inspectStage6TableReadEvidence } from '../api/stage6-revisions'
const workspace=ref<Stage6TableReadEvidenceInspectorWorkspace|null>(null),inspection=ref<Stage6TableReadEvidenceInspectionResult|null>(null),selectedBenchmarkId=ref(''),selectedRound=ref<1|2>(1),editorText=ref(''),loading=ref(false),errorMessage=ref(''),copyMessage=ref('')
const labels:Record<string,string>={request_valid:'检查请求',json_valid:'JSON 可解析',artifact_schema_valid:'桌读 Artifact Schema',p0_readiness_reverified:'P0 Readiness 重验',benchmark_binding_valid:'Benchmark 绑定',real_project_binding_valid:'真实项目绑定',round_binding_valid:'轮次绑定',session_reference_valid:'Session 绑定',table_read_schedule_verified:'桌读排期已核验',three_required_roles_present:'三角色意见齐全',reviewer_ids_match_verified_intake:'Reviewer ID 与 P0 一致',feedback_ids_unique:'Feedback ID 唯一',submitted_at_not_before_scheduled_at:'提交时间不早于桌读'}
onMounted(loadTemplate)
async function loadTemplate(){loading.value=true;errorMessage.value='';const response=await getStage6TableReadEvidenceInspector(selectedBenchmarkId.value,selectedRound.value);loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'桌读模板加载失败';return}workspace.value=response.data;selectedBenchmarkId.value=response.data.selected_benchmark_id;selectedRound.value=response.data.selected_round_number;editorText.value=response.data.template_raw_json;inspection.value=response.data.template_inspection}
async function runInspection(){loading.value=true;errorMessage.value='';const response=await inspectStage6TableReadEvidence({raw_json:editorText.value,expected_benchmark_id:selectedBenchmarkId.value,expected_round_number:selectedRound.value});loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'桌读证据检查失败';return}inspection.value=response.data}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{editorText.value=await file.text();errorMessage.value=''}catch(error){errorMessage.value=`导入失败：${(error as Error).message}`}finally{input.value=''}}
async function copyJson(){try{await navigator.clipboard.writeText(editorText.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)}
function checkLabel(value:string){return labels[value]??value}
</script>

<style scoped>
