.workspace-grid{max-width:1440px;margin:auto;display:grid;grid-template-columns:minmax(420px,.86fr) minmax(570px,1.14fr);gap:15px;align-items:start}.editor-card,.result-card{overflow:hidden;border:1px solid #523a48;border-radius:13px;background:rgba(28,18,25,.96)}.editor-card{position:sticky;top:15px}.editor-card>header,.result-card>header{padding:15px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #422e39}.editor-card h3,.result-card h3{margin:3px 0 0}.editor-card header span{color:#95818c;font:10px ui-monospace,monospace}.result-card header>b{font-size:10px;letter-spacing:.07em}.ready{color:#7ed9c3}.blocked{color:#ff94aa}.toolbar{padding:10px 13px;display:flex;align-items:center;gap:7px}.toolbar input{display:none}.toolbar span{color:#9c8993;font-size:10px}textarea{width:100%;min-height:650px;padding:16px;box-sizing:border-box;resize:vertical;border:0;border-block:1px solid #3c2933;outline:0;color:#dfd2d9;background:#100b0e;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.editor-card footer{padding:10px 13px;display:flex;justify-content:space-between;color:#95828b;font-size:10px}.editor-card footer b{color:#e3acc7}
.metrics{margin:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.metrics div{padding:9px;border-radius:7px;background:#2a1c25}.metrics span{display:block;color:#99858f;font-size:9px}.metrics strong{font-size:15px}.metrics div:last-child strong{color:#ff95ab}.identity-grid,.safety-grid{margin:0 14px 12px;display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.identity-grid span,.safety-grid span{padding:8px;border-radius:7px;color:#96828c;background:#261922;font-size:9px}.identity-grid b,.safety-grid b{float:right;max-width:65%;color:#e0d2d9;overflow-wrap:anywhere}.safety-grid b{color:#ff96ab}.hash-panel{margin:0 14px 12px;padding:10px;border:1px solid #5a4050;border-radius:9px;background:#160f14}.hash-panel div+div{margin-top:7px}.hash-panel span{display:block;color:#94818a;font-size:9px}.hash-panel code{display:block;color:#ddb5c8;overflow-wrap:anywhere;font-size:10px}.role-grid{margin:0 14px 12px;display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.role-grid article{padding:8px;border-radius:7px;background:#281a23}.role-grid span{display:block;color:#9d8993;font-size:8px}.role-grid strong{font-size:17px}.checks,.issues{margin:0 14px 13px}.checks h4,.issues h4{margin:0 0 7px}.checks>div{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.checks span{padding:7px;border-radius:6px;font-size:9px}.ok{color:#7dd8c4;background:#15372f}.fail{color:#f099ab;background:#3a1b27}.issues>article{margin:5px 0;padding:8px;border:1px solid #5a3d4a;border-radius:7px;background:#2b1922}.issues>article.warning{border-color:#6a542d;background:#2b2214}.issues article header{display:flex;gap:7px}.issues article b{color:#eb9cb1;font-size:8px}.issues .warning b{color:#e2be72}.issues code{color:#ccb9c1;font-size:9px}.issues article>span{display:block;margin-top:3px;color:#917d86;font-size:9px}.issues p{margin:2px 0 0;color:#c1b1b8;font-size:10px}
@media(max-width:1050px){.workspace-grid{grid-template-columns:1fr}.editor-card{position:static}textarea{min-height:450px}}@media(max-width:720px){.review-page{padding:18px 12px}.hero,.truth-lock,.selector-bar{align-items:flex-start;flex-direction:column}.selector-bar label{width:100%}.metrics,.role-grid{grid-template-columns:repeat(2,1fr)}.checks>div,.identity-grid,.safety-grid{grid-template-columns:1fr}}
</style>
